begin;
create extension if not exists pgtap with schema extensions;
set local search_path=public,extensions;
select no_plan();
\ir helpers/fms_visit_assignment_fixture.psql
insert into visit_assignment_fixture select 'loop_flow',create_fms_revision_with_audit((select id from visit_assignment_fixture where name='flow'));
reset role;
insert into visit_assignment_fixture select 'loop_'||stage_key,id from fms_stages where fms_flow_id=(select id from visit_assignment_fixture where name='loop_flow');
update fms_stages set planned_time_rule=jsonb_set(planned_time_rule,'{assignment,sources}',(planned_time_rule#>'{assignment,sources}')||jsonb_build_array(jsonb_build_object('sourceStageKey','demo','formTemplateId',form_template_id,'fieldKey','next_employee'))) where id=(select id from visit_assignment_fixture where name='loop_call');
update fms_stages set planned_time_rule=planned_time_rule||'{"decisionMode":"decision","decisionOptions":[{"key":"repeat","label":"Follow up again"},{"key":"exit","label":"Continue"}]}'::jsonb,default_next_stage_id=(select id from visit_assignment_fixture where name='loop_call') where id=(select id from visit_assignment_fixture where name='loop_demo');
insert into fms_branch_rules(fms_stage_id,source_type,condition_field,condition_operator,condition_value,next_stage_id,sort_order) values((select id from visit_assignment_fixture where name='loop_demo'),'outcome','outcome','equals','exit',(select id from visit_assignment_fixture where name='loop_negotiation'),0);
update fms_stages set planned_time_rule=planned_time_rule||'{"followUp":{"maxVisits":1,"onLimit":"escalate"}}'::jsonb where id=(select id from visit_assignment_fixture where name='loop_call');
set local role authenticated;
select lives_ok($$select publish_fms_flow_with_audit((select id from visit_assignment_fixture where name='loop_flow'))$$,'human follow-up loop with an exit publishes');
insert into visit_assignment_fixture select 'loop_instance',(submit_fms_form_and_progress_with_audit((select id from visit_assignment_fixture where name='form'),jsonb_build_object('next_employee',(select id from visit_assignment_fixture where name='b')),'fms_entry',(select id from fms_starter_assignments where fms_flow_id=(select id from visit_assignment_fixture where name='loop_flow') and user_profile_id=(select id from visit_assignment_fixture where name='a')),gen_random_uuid())->>'instance_id')::uuid;
select set_config('request.jwt.claim.sub',(select id::text from visit_assignment_fixture where name='b_auth'),true);
select submit_fms_form_and_progress_with_audit((select id from visit_assignment_fixture where name='form'),jsonb_build_object('next_employee',(select id from visit_assignment_fixture where name='c')),'fms_stage',(select id from fms_instance_stages where fms_instance_id=(select id from visit_assignment_fixture where name='loop_instance') and fms_stage_id=(select id from visit_assignment_fixture where name='loop_call')),gen_random_uuid());
select set_config('request.jwt.claim.sub',(select id::text from visit_assignment_fixture where name='c_auth'),true);
insert into visit_assignment_fixture select 'limit_visit',id from fms_instance_stages where fms_instance_id=(select id from visit_assignment_fixture where name='loop_instance') and fms_stage_id=(select id from visit_assignment_fixture where name='loop_demo');
create temporary table limit_request(request jsonb,preview jsonb,result jsonb);
grant all on limit_request to authenticated;
insert into limit_request(request) values(jsonb_build_object('kind','stage_form','instanceStageId',(select id from visit_assignment_fixture where name='limit_visit'),'formTemplateId',(select id from visit_assignment_fixture where name='form'),'answers',jsonb_build_object('next_employee',(select id from visit_assignment_fixture where name='d')),'outcome','repeat','remark','Needs more follow-up','checklist','{}'::jsonb));
update limit_request set preview=preview_fms_work_transition(request);
select ok((select preview->'requirements' ? 'Configured follow-up limit reached; manager review is required.' from limit_request),'preview explains the configured review hold');
update limit_request set result=transition_fms_work_with_audit(request,gen_random_uuid(),'[]',preview->>'fingerprint');
select is((select result->>'state' from limit_request),'workflow_on_hold','confirmed form reports the actual review hold');
select is((select status::text from fms_instances where id=(select id from visit_assignment_fixture where name='loop_instance')),'on_hold','instance is held');
select is((select status::text from fms_instance_stages where id=(select id from visit_assignment_fixture where name='limit_visit')),'in_progress','source work remains available for a resumed exit decision');
select ok((select form_submission_id is not null and escalation_count=1 from fms_instance_stages where id=(select id from visit_assignment_fixture where name='limit_visit')),'form and one escalation are preserved');
select is((select count(*)::integer from v_all_tasks where fms_instance_stage_id=(select id from visit_assignment_fixture where name='limit_visit')),1,'held open work remains in the employee task feed');
select set_config('request.jwt.claim.sub',(select id::text from visit_assignment_fixture where name='a_auth'),true);
select lives_ok($$select resume_fms_instance_with_audit((select id from visit_assignment_fixture where name='loop_instance'),'Reviewed follow-up limit; use the configured exit')$$,'authorized manager can resume review');
select set_config('request.jwt.claim.sub',(select id::text from visit_assignment_fixture where name='c_auth'),true);
update limit_request set request=jsonb_build_object('kind','complete','instanceStageId',(select id from visit_assignment_fixture where name='limit_visit'),'outcome','exit','remark','Continue after review','checklist','{}'::jsonb);
update limit_request set preview=preview_fms_work_transition(request);
select is((select transition_fms_work_with_audit(request,gen_random_uuid(),'[]',preview->>'fingerprint')->>'state' from limit_request),'successors_activated','resumed owner can exit using the locked saved form');
reset role;
select is((select count(*)::integer from fms_instance_stages where fms_instance_id=(select id from visit_assignment_fixture where name='loop_instance') and fms_stage_id=(select id from visit_assignment_fixture where name='loop_call')),1,'the capped repeat visit was never created');
select * from finish();
rollback;
